const checkPetReporterId = async (petId) => {
  try {
    const response = await fetch(`/api/pets/${petId}`);
    const pet = await response.json();
    console.log('Mascota:', pet);
    if (pet.reporterId) {
      console.log('ReporterId válido:', pet.reporterId);
    } else {
      console.log('No tiene reporterId');
    }
  } catch (error) {
    console.error('Error al obtener mascota:', error);
  }
};

checkPetReporterId('id-de-la-mascota');
